Build the room_bookings table with an EXCLUDE constraint. Prove it holds under concurrency: two sessions each insert an overlapping booking for the same room inside open transactions, and show that the second blocks and then fails on commit.
Solution
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE room_bookings (
id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
room_id int NOT NULL,
during tstzrange NOT NULL,
EXCLUDE USING gist (room_id WITH =, during WITH &&)
);
-- Session A -- Session B
BEGIN; BEGIN;
INSERT INTO room_bookings (room_id, during)
VALUES (1, tstzrange('2026-07-01','2026-07-05','[)'));
INSERT INTO room_bookings (room_id, during)
VALUES (1, tstzrange('2026-07-03','2026-07-08','[)'));
-- blocks, waiting on A
COMMIT; -- ERROR: conflicting key value violates
-- exclusion constraint
